SELECT e.name,count(p.oid)=1 AS exactly_one_signature,bool_and(md5(btrim(p.prosrc,E' \t\r\n'))=e.hash) AS exact_final_body,bool_and(pg_get_userbyid(p.proowner)='postgres') AS expected_owner FROM (VALUES ('cohort_assert_record_parent_v1','3efad7922565115432b0597a8016b866'),('cohort_guard_completion_record_identity_v1','16a32bce4ab3db319443607f6a3b6b0f'),('cohort_sync_training_session_from_terminal_record','aa26c641897d8b5836ac315b14e7bf27'),('cohort_assert_completion_request_v1','91b891d56e527b2865845b6d7219e386'),('complete_programme_session_and_advance','73dd1c80e8e5aa40f45459f8791ad8dc'),('complete_fixed_programme_occurrence_and_advance','0d291d03f0e6e480003c59d9fcd6f775'),('complete_training_session_record','941b64ec8567ec6be99fa0545ac75d15'),('correct_completed_performance_record','61bbffefe704a862fe0435e8b4c4b0dd'),('cohort_complete_backfilled_fixed_occurrence_at','b423f29db128863299c9bae8525e9038'),('cohort_guard_direct_result_write_v1','28b7e1f10c1d0c5500699677d4000754'),('cohort_guard_result_identity_v1','8f4789f5cbd228cc5a6a036af90649be'),('cohort_insert_training_session_result_tree','1dbd6cae013436449f411c9690508d56'),('cohort_completion_programme_body_v1','4ee56b58774ca2c2c37a94a148ab3017'),('cohort_completion_fixed_body_v1','81797afd8e33e09b54cf1f61e5441644'),('cohort_completion_standalone_body_v1','b41b6470f6173b2d98648c6e57123614'),('cohort_completion_correction_body_v1','8ed1a1c5afb5818a1f63d52ce51e9f01'),('cohort_completion_backfill_body_v1','ba57cdc2b911bfc8db0faf424ec4e575'),('complete_backfilled_fixed_programme_occurrence','6dbd1ba698eb5563f48df73c1885aa8f')) e(name,hash) LEFT JOIN pg_proc p ON p.pronamespace='public'::regnamespace AND p.proname=e.name GROUP BY e.name ORDER BY e.name;
